export function searchRules(query: string): { document: RuleDocument; snippet: string; score: number }[] {
  if (!query || query.trim().length < 2) return [];
  
  const terms = query.toLowerCase().split(/\s+/).filter(t => t.length > 1);
  
  const results = rulesDocuments.map((doc) => {
    const contentLower = doc.content.toLowerCase();
    const titleLower = doc.title.toLowerCase();
    
    let score = 0;
    let bestSnippetPos = -1;
    
    for (const term of terms) {
      if (titleLower.includes(term)) {
        score += 10;
      }
      
      let pos = 0;
      let termCount = 0;
      while ((pos = contentLower.indexOf(term, pos)) !== -1) {
        termCount++;
        if (bestSnippetPos === -1) bestSnippetPos = pos;
        pos += term.length;
      }
      score += termCount;
    }
    
    let snippet = "";
    if (bestSnippetPos >= 0) {
      const start = Math.max(0, bestSnippetPos - 80);
      const end = Math.min(doc.content.length, bestSnippetPos + 200);
      snippet = (start > 0 ? "..." : "") + doc.content.slice(start, end).trim() + (end < doc.content.length ? "..." : "");
    }
    
    return { document: doc, snippet, score };
  }).filter(r => r.score > 0);
  
  results.sort((a, b) => b.score - a.score);
  return results.slice(0, 10);
}
